#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
using namespace std;

int main() {
    string file_name;
    string word_to_search, word;
    int count = 0;

    cout << "Enter the filename : ";
    cin >> file_name;

    cout << "Enter word to count : ";
    cin >> word_to_search;

    ifstream file(file_name.c_str());

    if(file.is_open()) {
        while(file >> word) {
            if(word == word_to_search) {
                count++;
            }
        }
        cout << "The word \"" << word_to_search << "\" occurs " << count << " times in the file." << endl;
    } else {
        cout << "File named '" << file_name << "' does not exist." << endl;
    }

    file.close();
    return 0;
}
```
